<?php
declare(strict_types=1);
namespace App\Services\Finance;
use App\Models\Finance\{StudentInvoice,StudentPayment};
class FinanceDashboardService {
 public function data():array{$start=now()->startOfMonth();$end=now()->endOfMonth();$invoices=StudentInvoice::query();$payments=StudentPayment::query()->where('status','succeeded');$series=collect(range(11,0))->map(function($n){$d=now()->subMonths($n);return ['label'=>$d->translatedFormat('M Y'),'total'=>(string)StudentPayment::where('status','succeeded')->whereBetween('paid_at',[$d->copy()->startOfMonth(),$d->copy()->endOfMonth()])->sum('amount')];})->push(['label'=>now()->translatedFormat('M Y'),'total'=>(string)(clone $payments)->whereBetween('paid_at',[$start,$end])->sum('amount')]);return ['stats'=>['Tagihan bulan berjalan'=>(string)(clone $invoices)->whereBetween('billing_month',[$start,$end])->sum('total'),'Pembayaran bulan berjalan'=>(string)(clone $payments)->whereBetween('paid_at',[$start,$end])->sum('amount'),'Total tunggakan'=>(string)(clone $invoices)->whereNotIn('status',['paid','cancelled','draft'])->sum('outstanding_amount'),'Siswa memiliki tunggakan'=>(clone $invoices)->whereNotIn('status',['paid','cancelled','draft'])->where('outstanding_amount','>',0)->distinct()->count('student_id'),'Pembayaran hari ini'=>(string)(clone $payments)->whereDate('paid_at',today())->sum('amount'),'Tagihan jatuh tempo'=>(clone $invoices)->where('due_date','<',today())->where('outstanding_amount','>',0)->count(),'Tagihan lunas'=>(clone $invoices)->where('status','paid')->count(),'Tagihan belum lunas'=>(clone $invoices)->whereIn('status',['open','partial','overdue'])->count()],'series'=>$series,'recent'=>(clone $payments)->with(['student','invoice'])->latest('paid_at')->limit(8)->get(),'due'=>(clone $invoices)->with('student')->where('outstanding_amount','>',0)->whereNotIn('status',['cancelled','draft'])->orderBy('due_date')->limit(8)->get(),'methods'=>(clone $payments)->selectRaw('payment_method, sum(amount) total')->groupBy('payment_method')->pluck('total','payment_method'),'statuses'=>(clone $invoices)->whereIn('status',['open','partial','paid','overdue'])->selectRaw('status, count(*) total')->groupBy('status')->pluck('total','status')];}
}
